sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Illusions_(1982_film)> 
    <http://dbpedia.org/resource/It's_a_Wonderful_Afterlife>
  }

  # director (prefer dbo, fallback to dbp)
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?film dbp:director ?director . }

  # director's birth date (prefer dbo, fallback to dbp)
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDate . }

  # optional readable labels
  OPTIONAL { ?film rdfs:label ?filmLabel .
             FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorName .
             FILTER (lang(?directorName) = "en") }
}
ORDER BY ?film
LIMIT 100

